use crate::domains::kernel_opt::corpus::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        // ============================================================
        // -- occupancy-before-async-consumer-ada -- Batch 148 /
        // Research 174 / Plan 133 (the regime boundary + the route split).
        KernelRule {
            rule_id: "occupancy-before-async-consumer-ada".to_string(),
            gpu_concept: "Deeper async staging and higher occupancy are the SAME budget spent two ways, and on compute-bound sm_89-class silicon occupancy wins the exchange -- but ONLY when the +1 block/SM is bought with SAVED SHARED MEMORY, never with capped registers and never with a shrunken tile. The boundary is dual-sourced. EXTERNAL (Bakhshaliyev RTX 4090 FP8 GEMM series, stock clocks): cp.async double buffering measured WORSE than the synchronous path -- 'the overhead of managing two SMEM buffers and commit/wait groups cost more than the overlap saved. 318-418 TFLOPS' against the 546 winner; `__launch_bounds__(256, 2/4)` cost -20% ('The compiler obeys launch_bounds as a maximum, not a target'); register-level double buffering v7 = 438 (spills erased the gains). The winning occupancy purchase was an SMEM saving: 'Going from stride-144 padded to stride-128 XOR-swizzled also saved enough shared memory to fit 3 blocks per SM instead of 2. That's 24 warps instead of 16, which helps hide the 26-cycle MMA latency' -- the BK=128 tile was 'the single biggest win' (473 -> 513) and the swizzle's second dividend took 513 -> 546. OUR LANE (riir-ai Bench 933, the Issue-918 rung-A occupancy arm, 4090 sm_89, production q8 packed-weight family, bitdiffs 0 in every cell): buying 24 warps with the REGISTER route is refuted three ways -- (1) `__launch_bounds__(256, 3)` caps regs at 85 and the 32x32-warp-tile body (64 accumulator regs + working set) spills: 80 regs + 56 B local -> 172.8 TF = 0.516x vs v10t's 335.1 (the B895 spill-fragility law, then measured a 4th time); the decode-stripped twin spilled WORSE (104 B -> 0.340x) -- without the decode dependency chain the scheduler stretches differently, so 'the 85-reg cap cannot hold the tile, with or without decode'; (2) the tile-shrink route (v12: 64-row blocks, 32 accumulator regs, spill-free at 75 regs, the ONE route the register file leaves open) still measured 0.648x -- 'the halved tile doubles ldmatrix + A-LDS traffic per useful mma and doubles B staging across the doubled x-grid ... the extra 8 warps/SM cannot pay for their own feed' -- tile economics beat occupancy; (3) the ceiling datum: with ALL decode stripped the 16-warp structure sits at 64.6% (427 TF nodecode) -- 'even with ZERO decode the 16-warp structure sits at the bottom of the external 65-80% band: the residual wall is feed ILP at 4 warps/scheduler, reg-capped'. The register file is the wall in BOTH directions on sm_89 (16 warps x 128 regs fills it; 24 warps needs <=85 and spills) and sm_89 has NO setmaxnreg -- the sm_90+ register-reallocation escape hatch does not exist here (see setmaxnreg-fit-gate-elected-arrive for the sm_90+ form). DECISION ORDER for a compute-bound consumer kernel on this silicon class: (1) first try to SAVE SMEM per block (XOR swizzle to the power-of-two stride, PACKED operand formats -- our own packed-code 4x stage shrink is the same purchase: it bought the double-buffered ring inside the DEFAULT budget, see packed-code-cpasync-stage-per-use-prmt-decode) and let the saved bytes fit the +1 block/SM; (2) keep the async ring at the depth that fits AFTER the saving (our production v10t KEEPS its 2-deep cp.async ring -- it wins at TOKS=64; ring depth >=3 closed smem-infeasible at TOKS=128 / occupancy-neutral at TOKS=64, Bench 933 section 5); (3) NEVER force occupancy through `__launch_bounds__` min-blocks (the register cap spills: measured 20x-slower-class on the CloudRift FFMA kernel, 0.516x on ours, -20% on the external FP8 lane -- three independent cells of the same law); (4) NEVER buy the extra warps with a halved tile without a probe-first cell (v12 is the measured counter-example: spill-free and still -35%). Regime: the boundary INVERTS in the latency/occupancy-starved regime -- at low occupancy or a launch-bound pass, deeper cp.async staging IS the lever (cpasync-multistage-tile-pipeline's own win record; the CloudRift gate_up 4096x28672 cell where 896 CTAs on 80 SMs already hid the latency is the measured middle). Hardware-facts rider (external, consumer Ada/AD102): the smem wall measured at 32 KB x 3.125 blocks; registers ~76/thread x 256 threads x 4 > 65,536; NCU at the ceiling showed tensor pipe ~89%, memory 73%, 3 blocks/SM. Distinct from `cpasync-multistage-tile-pipeline` (the staging MECHANICS and its win record in the starved regime; this is the REGIME BOUNDARY that decides when deepening pays -- the sm_89 loser cell rides that rule as a rider), from `autotune-warps-stages` (its Batch-130/138 riders already record the launch_bounds-forcing and deep-ring losers as sweep negatives; this rule carries the ROUTE SPLIT that explains them -- the sweep surface this boundary rides ON), from `register-double-buffer-operand-pipeline` (register FRAGMENT double-buffering under an even ring; the external 438 cell is that family's spill boundary, cited here as route-1 evidence), from `smem-budget-single-buffer-refill-at-kill-points` (the budget-CLAMPED staging family -- accept single-buffering under pressure; this rule's purchase order AVOIDS the pressure by shrinking bytes first), from `occupancy-grid-cap-refuted-uncapped-default` (GRID sizing at the launch level; this is BLOCKS-PER-SM residency at the resource level), from `grid-collapsing-mega-kernel-occupancy-trap` (the mega-kernel occupancy trap; the same resource arithmetic, opposite direction -- that rule warns collapsing grids starve occupancy, this rule warns buying it back the wrong way), from `setmaxnreg-fit-gate-elected-arrive` (the sm_90+ escape hatch this rule's silicon lacks -- the fit-gate arithmetic is the first thing to re-run when the target changes), and from `packed-code-cpasync-stage-per-use-prmt-decode` (our own smem-saving PURCHASE instance -- the 4x stage shrink; this rule is the purchase ORDER that instance satisfies). Source: Research 174 (Vugar Bakhshaliyev, 'Unlocking 473 TFLOPS on RTX 4090' + 'Continue: Unlocking 587 TFLOPS on the RTX 4090', LinkedIn Pulse Feb 18/21 2026 -- Part 2 'The Dead Ends', 'The mbarrier Experiment', and the Part 2 stock-clock ladder; quotes verified full-text 2026-09-16) + riir-ai Bench 933 sections 4/6/7 (read-only citation; the owning lane keeps its code -- Issue 918 closed gate-physics-capped at the 1.047x row best). Batch 148 / Plan 133 / Research 174.".to_string(),
            ref_shape: "// naive (compute-bound sm_89): chase latency-hiding DEPTH and force\n// occupancy through the register cap -- two ways to lose the same\n// budget. (a) deepen the cp.async ring: more smem per block, more\n// commit/wait groups, fewer blocks resident; (b) force min-blocks:\n// __launch_bounds__ clamps the register budget and the tile spills.\nconst TILE_K: usize = 128;\nconst ROWS: usize = 128;\n\n#[derive(Clone, Copy)]\nstruct Cfg {\n    stages: usize,       // cp.async ring depth\n    min_blocks: usize,   // __launch_bounds__ min-blocks-per-SM\n    max_regs: usize,     // the compiler's cap once min_blocks is set\n}\n\nfn gemm_naive(cfg: Cfg, groups: usize, a: &[u32], b: &[i8]) -> i32 {\n    // stride-144 PADDED stage: 128 rows x 144 B = 18,432 B/block --\n    // only 2 blocks fit the ~100 KB SM budget, 16 warps/SM\n    let stage_bytes = ROWS * 144;\n    let blocks_that_fit = 100_000 / stage_bytes; // 2\n\n    // route (b): force a 3rd block -- the cap drops to 85 regs and the\n    // 64-accumulator tile spills (B933: 56 B -> 0.516x; nodecode 104 B\n    // -> 0.340x; external launch_bounds -20%)\n    let spilled = cfg.min_blocks > blocks_that_fit;\n\n    // route (a): deepen the ring anyway -- 318-418 vs 546 external;\n    // the commit/wait overhead exceeds the overlap at high occupancy\n    let mut acc = 0i32;\n    for g in 0..groups {\n        for s in 0..cfg.stages {\n            commit_group(); // depth buys nothing the scheduler hides free\n        }\n        wait_all();\n        acc += mma_group(a, b, g, cfg.max_regs, spilled);\n    }\n    acc\n}\n\nfn commit_group() {}\nfn wait_all() {}\nfn mma_group(_a: &[u32], _b: &[i8], _g: usize, max_regs: usize, spilled: bool) -> i32 {\n    // spilled work goes through local memory: the measured halving\n    let penalty = if spilled { 2 } else { 1 };\n    (max_regs as i32) / penalty\n}\n".to_string(),
            opt_pattern: "// optimized: buy the +1 block/SM with SAVED SMEM, not capped regs.\n// (1) XOR-swizzle to the power-of-two stride: 18,432 -> 16,384 B/block\n//     (external: 3 blocks/SM, 24 warps, hides the 26-cycle MMA latency;\n//     the ladder 473 -> 513 was the tile, 513 -> 546 was THIS saving);\n// (2) or PACK the operand format (our lane: 2-bit codes shrink the A\n//     stage 4x -- the same purchase, different coin);\n// (3) KEEP the ring at the depth that fits AFTER the saving (v10t's\n//     2-deep ring wins; >=3 is smem-infeasible or occupancy-neutral);\n// (4) one __syncthreads per group (the hw barrier -- see\n//     hw-barrier-beats-mbarrier-polling); never min-blocks forcing.\nconst ROWS: usize = 128;\nconst STAGES: usize = 2; // the depth that fits post-saving\n\n#[repr(C, align(16))]\nstruct StageRow([u32; 32]); // 128 B swizzled row (not 144 B padded)\n\nfn xor_swizzle(flat: usize) -> usize {\n    let row = flat / ROWS;\n    (row * ROWS) + ((flat % ROWS) ^ row) // conflict-free BOTH directions\n}\n\nfn blocks_resident() -> usize {\n    let stage_bytes = ROWS * 128; // 16,384 B after the swizzle saving\n    100_000 / stage_bytes // 3 blocks/SM -- 24 warps, no reg cap touched\n}\n\nfn gemm_optimized(groups: usize, a_codes: &[u32], b: &[i8], stage: &mut [StageRow]) -> i32 {\n    let mut acc = 0i32;\n    fill_stage(&a_codes[..], stage, 0); // prologue: group 0\n    for g in 0..groups {\n        if g + 1 < groups {\n            // next group issued MID-compute across the 2-deep ring --\n            // fire-and-forget, NO extra commit/wait groups\n            fill_stage(&a_codes[(g + 1) * code_span(g + 1)..], stage, (g + 1) % STAGES);\n        }\n        barrier(); // ONE hw barrier per group (BAR.SYNC)\n        acc += mma_group_swizzled(stage, b, g);\n    }\n    acc\n}\n\nfn fill_stage(src: &[u32], stage: &mut [StageRow], slot: usize) {\n    for (i, w) in src.iter().enumerate().take(ROWS * 32) {\n        let row = i / 32;\n        stage[slot * ROWS + row].0[xor_swizzle(i) % 32] = *w;\n    }\n}\nfn code_span(_g: usize) -> usize {\n    ROWS * 32\n}\nfn barrier() {}\nfn mma_group_swizzled(_stage: &[StageRow], _b: &[i8], _g: usize) -> i32 {\n    1 // 128 regs intact: no launch_bounds cap, no spill, 24 warps/SM\n}\n".to_string(),
        },

        // ============================================================
        // -- hw-barrier-beats-mbarrier-polling -- Batch 148 /
        // Research 174 / Plan 133 (the polling issue-slot cost).
        KernelRule {
            rule_id: "hw-barrier-beats-mbarrier-polling".to_string(),
            gpu_concept: "For CONSUMER-side intra-block staging handoff in a compute-bound all-thread-wait kernel, the hardware barrier (BAR.SYNC via `__syncthreads`) is optimal on this silicon class and software mbarrier polling is a measured anti-pattern: on the external sm_89 FP8 GEMM lane, replacing `__syncthreads` with an all-thread mbarrier poll cost -16% (syncthreads 590 TF, mbar_poll 494) and the yield-hint variant -19% (mbar_yield 478) -- mechanism, in the source's words: 'Software polling burns issue slots on test instructions that could be running MMA or loads.' Every polling thread interleaves test-and-branch instructions with the mma feed, so the poll competes for exactly the issue slots the compute body needs; the hardware barrier parks the warp in the barrier unit instead. The design consequence lands on warp-specialization plans: the external source's warp-spec rung measured 378 vs 546 ('Our implementation was broken -- 0 effective blocks') and our lane's bounded disposition agrees on sm_89 -- warp-spec buys NO register headroom (one 128-reg allocation for all warps, no setmaxnreg) and is bounded by the 7.3% decode share it could take off the consumer chain (Bench 933 sections 2/3/6). REGIME BOUNDARY (load-bearing -- the counter-case is in-corpus and NOT contradicted): when the barrier tracks ASYNC DMA COMPLETION rather than consumer handoff, mbarrier is the ONLY correct mechanism (BAR.SYNC cannot observe a TMA/cp.async.bulk transfer) and its cost is one exit-fast spin -- the CloudRift TMA lane's `mbarrier.try_wait.parity` 'empirically exits on first read because the 44 KiB transfer is smaller than the compute phase' (tma-single-issuer-bulk-tile's rider). The split: PRODUCER-completion tracking (few issuers, transfer-dominated, sm_90+ TMA) -> mbarrier with expect_tx; CONSUMER handoff at tile boundaries (all threads wait, compute-bound, sm_89-class) -> the hardware barrier, once per group. Barrier COUNT composes with mechanism: the winning external shape ran paired K-step fragment loading under ONE `__syncthreads()` per K-iteration (1-2% on large matrices, up to 2.5% at 2048^3) -- the same one-barrier-per-group discipline our production v10t runs ('wait_all + one `__syncthreads` per group', Bench 933 section 2). Distinct from `spin-barrier-needs-co-residency-capped-launch` (that rule's subject is the CO-RESIDENCY legality of software grid barriers -- deadlocks when peers are not resident; this rule's subject is the THROUGHPUT cost of polling a block-local barrier -- a software barrier can be perfectly legal and still -16% slow), from `masked-branchless-wait-collapse` (collapses the WAIT SHAPE when the data itself encodes readiness; this chooses the barrier MECHANISM when a wait is unavoidable -- they compose: collapse what the masks can carry, hardware-barrier what cannot), from `barrier-free-per-dependency-wait-from-loop-counters` + `shared-counter-decode-producer-progress` (barrier ELIMINATION via dependency counters; this is the floor under those eliminations -- when the counter route is unavailable, the hw barrier is the measured-optimal residue, never a poll loop), from `tma-single-issuer-bulk-tile` (the TMA regime where the mbarrier IS correct -- this rule carries that rule's try_wait-is-cheap cell as its own regime boundary; neither direction subsumes the other), from `setmaxnreg-fit-gate-elected-arrive` (the sm_90+ warp-spec handshake gates -- named-band bar.sync over the compute band is the same hw-barrier preference one silicon up; this rule is the sm_89 compute-bound measurement), from `plane-specialization-load-compute-role-split` (the warp-spec ROLE-SPLIT design this rule hardens -- on sm_89 without async MMA the split has nothing to dedicate a producer warp to, and polling its handoff doubles the loss), and from `defensive-sync-peephole-tile-body-scope` (removing REDUNDANT syncs; this rule fixes the mechanism of the syncs that REMAIN). Source: Research 174 (Bakhshaliyev Part 2 'The mbarrier Experiment' -- the 590/494/478 cells + the issue-slot quote; the singlesync cells; the warp-spec 378 cell; quotes verified full-text 2026-09-16) + riir-ai Bench 933 sections 2/3/6 (read-only citations). Batch 148 / Plan 133 / Research 174.".to_string(),
            ref_shape: "// naive: replace the tile-loop __syncthreads with an all-thread\n// software poll on an mbarrier/flag -- every thread interleaves\n// test-and-branch with the mma feed, burning issue slots the compute\n// body needs (external sm_89: -16% poll, -19% yield-variant).\nstruct Mbar {\n    phase: bool,\n}\n\nimpl Mbar {\n    fn wait_poll(&self, phase: bool) {\n        // mbarrier.try_wait spin: test instructions on the issue slots\n        // 'that could be running MMA or loads'\n        while self.phase != phase {\n            spin_hint(); // nanosleep/yield variant: -19%\n        }\n    }\n}\n\nfn gemm_polled(groups: usize, stage: &mut [i8], b: &[i8], mbar: &Mbar) -> i32 {\n    let mut acc = 0i32;\n    let mut phase = false;\n    for g in 0..groups {\n        fill_stage(g, stage); // producer half (all threads cooperate)\n        mbar.wait_poll(phase); // EVERY thread polls -- the -16% cell\n        phase = !phase;\n        acc += mma_group(stage, b, g);\n    }\n    acc\n}\n\nfn fill_stage(_g: usize, _stage: &mut [i8]) {}\nfn mma_group(_stage: &[i8], _b: &[i8], _g: usize) -> i32 {\n    1\n}\nfn spin_hint() {}\n".to_string(),
            opt_pattern: "// optimized: the hardware barrier parks the warp in the barrier unit\n// -- zero issue slots -- and the winning shape pairs the K-step\n// fragment loads under ONE __syncthreads per group (external 1-2.5%,\n// and our v10t runs the same one-barrier discipline at 2-deep ring).\nconst ROWS: usize = 128;\n\nfn gemm_hw_barrier(groups: usize, a: &[u32], b: &[i8], stage: &mut [[u32; 32]]) -> i32 {\n    let mut acc = 0i32;\n    fill_stage(&a[..ROWS * 32], stage, 0); // prologue: group 0\n    for g in 0..groups {\n        let nxt = (g + 1) % 2;\n        if g + 1 < groups {\n            // next group's fill issued BEFORE the barrier, paired with\n            // the current group's fragment loads -- one wait covers both\n            fill_stage(&a[(g + 1) * ROWS * 32..], stage, nxt);\n        }\n        barrier(); // __syncthreads: BAR.SYNC, the 590-TF cell\n        acc += mma_step(stage[g % 2], b, g);\n    }\n    acc\n}\n\nfn fill_stage(src: &[u32], stage: &mut [[u32; 32]], slot: usize) {\n    for row in 0..ROWS {\n        for w in 0..32 {\n            stage[slot][row.min(ROWS - 1)] = src[row * 32 + w];\n        }\n    }\n}\nfn barrier() {} // the hw barrier unit -- no issue-slot cost\nfn mma_step(_stage: [u32; 32], _b: &[i8], _g: usize) -> i32 {\n    1\n}\n".to_string(),
        },
    ]
}
